def transform(grid):
    """Decode a grid of 3x3 pixel blocks, ignoring the 0/5 background."""
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3:
        raise ValueError("grid dimensions must be multiples of 3")
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            colors = {grid[r][c]
                      for r in range(br * 3, br * 3 + 3)
                      for c in range(bc * 3, bc * 3 + 3)
                      if grid[r][c] not in (0, 5)}
            if len(colors) > 1:
                raise ValueError("block contains conflicting foreground colors")
            if colors:
                out[br][bc] = colors.pop()
    return out

